Set-StrictMode -Version Latest

function Read-TaskStore {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        return @()
    }

    $content = Get-Content -LiteralPath $Path -Raw
    if ([string]::IsNullOrWhiteSpace($content)) {
        return @()
    }

    $parsed = ConvertFrom-Json -InputObject $content
    return @($parsed)
}

function Write-TaskStore {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Tasks
    )

    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    $temporary = "$Path.$PID.tmp"
    $json = ConvertTo-Json -InputObject @($Tasks) -Depth 8
    [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
    Move-Item -LiteralPath $temporary -Destination $Path -Force
}

function Read-TaskForgeConfig {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        return [ordered]@{}
    }

    $content = Get-Content -LiteralPath $Path -Raw
    if ([string]::IsNullOrWhiteSpace($content)) {
        return [ordered]@{}
    }

    $config = ConvertFrom-Json -InputObject $content -AsHashtable
    if ($config -isnot [System.Collections.IDictionary]) {
        throw 'Configuration must be a JSON object.'
    }

    foreach ($key in $config.Keys) {
        Assert-TaskForgeConfigValue -Key $key -Value $config[$key]
    }
    return $config
}

function Write-TaskForgeConfig {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][System.Collections.IDictionary]$Config
    )

    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    $temporary = Join-Path $parent ".$([System.IO.Path]::GetFileName($Path)).$PID.$([guid]::NewGuid()).tmp"
    try {
        $json = ConvertTo-Json -InputObject $Config -Depth 4
        [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
        [System.IO.File]::Move($temporary, $Path, $true)
    }
    finally {
        if (Test-Path -LiteralPath $temporary) {
            Remove-Item -LiteralPath $temporary -Force
        }
    }
}

function Assert-TaskForgeConfigValue {
    param(
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)]$Value
    )

    switch ($Key) {
        'dataFile' {
            if ($Value -isnot [string] -or [string]::IsNullOrWhiteSpace($Value)) {
                throw 'Configuration value dataFile must be a non-empty path.'
            }
        }
        'defaultJson' {
            if ($Value -isnot [bool]) {
                throw 'Configuration value defaultJson must be true or false.'
            }
        }
        default {
            throw "Unknown configuration key: $Key"
        }
    }
}

function ConvertTo-TaskForgeBoolean {
    param(
        [Parameter(Mandatory)]$Value,
        [Parameter(Mandatory)][string]$Name
    )

    if ($Value -is [bool]) {
        return $Value
    }

    $text = [string]$Value
    if ($text.Equals('true', [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    if ($text.Equals('false', [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    throw "$Name must be true or false."
}

function Resolve-TaskForgeConfiguredPath {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$ConfigFile
    )

    if ([System.IO.Path]::IsPathFullyQualified($Path)) {
        return [System.IO.Path]::GetFullPath($Path)
    }

    $configDirectory = Split-Path -Parent $ConfigFile
    return [System.IO.Path]::GetFullPath((Join-Path $configDirectory $Path))
}

function ConvertFrom-TaskForgeArguments {
    param([AllowEmptyCollection()][string[]]$Arguments)

    $options = [ordered]@{}
    for ($index = 0; $index -lt $Arguments.Count; $index++) {
        $token = $Arguments[$index]
        if (-not $token.StartsWith('--')) {
            throw "Unexpected argument: $token"
        }

        $name = $token.Substring(2)
        if ([string]::IsNullOrWhiteSpace($name)) {
            throw 'Option name cannot be empty.'
        }
        if ($options.Contains($name)) {
            throw "Duplicate option: --$name"
        }

        if (($index + 1) -lt $Arguments.Count -and -not $Arguments[$index + 1].StartsWith('--')) {
            $options[$name] = $Arguments[++$index]
        }
        else {
            $options[$name] = $true
        }
    }

    return $options
}

function Get-RequiredOption {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][string]$Name
    )

    if (-not $Options.Contains($Name) -or $Options[$Name] -is [bool] -or
        [string]::IsNullOrWhiteSpace([string]$Options[$Name])) {
        throw "Missing required option: --$Name"
    }
    return [string]$Options[$Name]
}

function Assert-KnownOptions {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Allowed
    )

    foreach ($name in $Options.Keys) {
        if ($name -notin $Allowed) {
            throw "Unknown option: --$name"
        }
    }
}

function Write-TaskForgeOutput {
    param(
        [Parameter(Mandatory)]$Value,
        [Parameter(Mandatory)][bool]$AsJson
    )

    if ($AsJson) {
        ConvertTo-Json -InputObject $Value -Depth 8 -Compress
    }
    else {
        [string]$Value
    }
}

Export-ModuleMember -Function *

[CmdletBinding()]
param(
    [Parameter(Position = 0)]
    [string]$Command = 'help',

    [Parameter(Position = 1, ValueFromRemainingArguments)]
    [string[]]$CliArguments = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

try {
    $configAction = $null
    $configKey = $null
    $configValue = $null
    if ($Command.Equals('config', [System.StringComparison]::OrdinalIgnoreCase)) {
        if ($CliArguments.Count -gt 0 -and -not $CliArguments[0].StartsWith('--')) {
            $configAction = $CliArguments[0]
            $CliArguments = @($CliArguments | Select-Object -Skip 1)
        }
        if ($configAction -in @('set', 'get') -and $CliArguments.Count -gt 0 -and -not $CliArguments[0].StartsWith('--')) {
            $configKey = $CliArguments[0]
            $CliArguments = @($CliArguments | Select-Object -Skip 1)
        }
        if ($configAction -eq 'set' -and $CliArguments.Count -gt 0 -and -not $CliArguments[0].StartsWith('--')) {
            $configValue = $CliArguments[0]
            $CliArguments = @($CliArguments | Select-Object -Skip 1)
        }
    }

    $options = ConvertFrom-TaskForgeArguments -Arguments $CliArguments
    $defaultConfigFile = Join-Path ([Environment]::GetFolderPath('UserProfile')) '.taskforge\config.json'
    $configFile = if ($options.Contains('config-file')) {
        [System.IO.Path]::GetFullPath((Get-RequiredOption -Options $options -Name 'config-file'))
    }
    else {
        $defaultConfigFile
    }
    $config = Read-TaskForgeConfig -Path $configFile
    $defaultDataFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/tasks.json'
    $dataFile = if ($options.Contains('data-file')) {
        Get-RequiredOption -Options $options -Name 'data-file'
    }
    elseif ($config.Contains('dataFile')) {
        Resolve-TaskForgeConfiguredPath -Path $config['dataFile'] -ConfigFile $configFile
    }
    else {
        $defaultDataFile
    }
    $asJson = if ($options.Contains('json')) {
        ConvertTo-TaskForgeBoolean -Value $options['json'] -Name '--json'
    }
    elseif ($config.Contains('defaultJson')) {
        [bool]$config['defaultJson']
    }
    else {
        $false
    }

    switch ($Command.ToLowerInvariant()) {
        'add' {
            Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'config-file', 'json')
            $title = Get-RequiredOption -Options $options -Name 'title'
            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $task = [ordered]@{
                id = $nextId
                title = $title.Trim()
                description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
                status = 'pending'
                createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            }
            Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
            if ($asJson) {
                Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
            }
            else {
                "Added task ${nextId}: $($task.title)"
            }
        }
        'list' {
            Assert-KnownOptions -Options $options -Allowed @('data-file', 'config-file', 'json')
            $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
            if ($asJson) {
                Write-TaskForgeOutput -Value $tasks -AsJson $true
            }
            elseif ($tasks.Count -eq 0) {
                'No tasks.'
            }
            else {
                $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
            }
        }
        'complete' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'config-file', 'json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
            if ($null -eq $task) {
                throw "Task $id was not found."
            }
            $task.status = 'completed'
            Write-TaskStore -Path $dataFile -Tasks $tasks
            if ($asJson) {
                Write-TaskForgeOutput -Value $task -AsJson $true
            }
            else {
                "Completed task $id."
            }
        }
        'remove' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'config-file', 'json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
            if ($remaining.Count -eq $tasks.Count) {
                throw "Task $id was not found."
            }
            Write-TaskStore -Path $dataFile -Tasks $remaining
            $summary = [pscustomobject]@{ removedId = $id }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                "Removed task $id."
            }
        }
        'config' {
            Assert-KnownOptions -Options $options -Allowed @('config-file', 'json')
            if ([string]::IsNullOrWhiteSpace($configAction)) {
                throw 'Missing config action: set, get, or list.'
            }

            switch ($configAction.ToLowerInvariant()) {
                'set' {
                    if ([string]::IsNullOrWhiteSpace($configKey) -or $null -eq $configValue) {
                        throw 'Usage: config set KEY VALUE [--config-file PATH] [--json].'
                    }

                    $value = switch ($configKey) {
                        'dataFile' { [string]$configValue }
                        'defaultJson' { ConvertTo-TaskForgeBoolean -Value $configValue -Name 'defaultJson' }
                        default { throw "Unknown configuration key: $configKey" }
                    }
                    Assert-TaskForgeConfigValue -Key $configKey -Value $value
                    $updatedConfig = [ordered]@{}
                    foreach ($key in $config.Keys) {
                        $updatedConfig[$key] = $config[$key]
                    }
                    $updatedConfig[$configKey] = $value
                    Write-TaskForgeConfig -Path $configFile -Config $updatedConfig

                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $configKey; value = $value }) -AsJson $true
                    }
                    else {
                        "Set $configKey."
                    }
                }
                'get' {
                    if ([string]::IsNullOrWhiteSpace($configKey)) {
                        throw 'Usage: config get KEY [--config-file PATH] [--json].'
                    }
                    if ($configKey -notin @('dataFile', 'defaultJson')) {
                        throw "Unknown configuration key: $configKey"
                    }
                    if (-not $config.Contains($configKey)) {
                        throw "Configuration key is not set: $configKey"
                    }

                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $configKey; value = $config[$configKey] }) -AsJson $true
                    }
                    elseif ($config[$configKey] -is [bool]) {
                        ([bool]$config[$configKey]).ToString().ToLowerInvariant()
                    }
                    else {
                        [string]$config[$configKey]
                    }
                }
                'list' {
                    if ($null -ne $configKey -or $null -ne $configValue) {
                        throw 'Usage: config list [--config-file PATH] [--json].'
                    }

                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]$config) -AsJson $true
                    }
                    else {
                        Get-Content -LiteralPath (Join-Path (Split-Path -Parent $PSScriptRoot) 'assets/config.txt')
                        if ($config.Count -eq 0) {
                            'No settings.'
                        }
                        else {
                            foreach ($key in @('dataFile', 'defaultJson')) {
                                if ($config.Contains($key)) {
                                    $displayValue = if ($config[$key] -is [bool]) {
                                        ([bool]$config[$key]).ToString().ToLowerInvariant()
                                    }
                                    else {
                                        [string]$config[$key]
                                    }
                                    "$key = $displayValue"
                                }
                            }
                        }
                    }
                }
                default {
                    throw "Unknown config action: $configAction"
                }
            }
        }
        'help' {
            Assert-KnownOptions -Options $options -Allowed @('config-file')
            @'
TaskForge
  add --title TEXT [--description TEXT] [--data-file PATH] [--config-file PATH] [--json [BOOL]]
  list [--data-file PATH] [--config-file PATH] [--json [BOOL]]
  complete --id ID [--data-file PATH] [--config-file PATH] [--json [BOOL]]
  remove --id ID [--data-file PATH] [--config-file PATH] [--json [BOOL]]
  config set KEY VALUE [--config-file PATH] [--json [BOOL]]
  config get KEY [--config-file PATH] [--json [BOOL]]
  config list [--config-file PATH] [--json [BOOL]]
'@
        }
        default {
            throw "Unknown command: $Command"
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}
